wrap_x=bool(wrap_x); wrap_y=bool(wrap_y)

# load plots
plots = {}
for pid, terrain, continent, imp in cur.execute('SELECT ID, TerrainType, ContinentType, IsImpassable FROM Plots'):
    x,y=pid%width, pid//width
    plots[(x,y)]={'terrain':terrain,'impassable':bool(imp)}

# features
for pid, feature in cur.execute('SELECT ID, FeatureType FROM PlotFeatures'):
    x,y=pid%width, pid//width
    plots[(x,y)]['feature']=feature

