for pid, ne, w, nw, eflow, seflow, swflow in cur.execute('SELECT ID, IsNEOfRiver, IsWOfRiver, IsNWOfRiver, EFlowDirection, SEFlowDirection, SWFlowDirection FROM PlotRivers'):
    x,y=pid%width, pid//width
    river_flags[(x,y)]={'NE':bool(ne),'W':bool(w),'NW':bool(nw)}

# axial conversions (odd-q)
def offset_to_axial(x,y):
    q=x
    r=y - (x - (x&1))//2
    return q,r

def axial_to_offset(q,r):
    x=q
    y=r + (q - (q&1))//2
    return x,y

AXIAL_DIRS = {
    'E': (1,0),
    'W': (-1,0),
    'NE': (1,-1),
    'NW': (0,-1),
    'SE': (0,1),
    'SW': (-1,1),
}

# neighbors in axial

def neighbor(x,y,dir_name):
    q,r=offset_to_axial(x,y)
    dq,dr=AXIAL_DIRS[dir_name]
    nq,nr=q+dq,r+dr
    nx,ny=axial_to_offset(nq,nr)
    if wrap_x:
        nx%=width
    if wrap_y:
        ny%=height
    if 0<=nx<width and 0<=ny<height:
        return (nx,ny)
    return None


def neighbors(x,y):
    out=[]
    for d in AXIAL_DIRS:
        n=neighbor(x,y,d)
        if n is not None:
            out.append(n)
    return out

# river adjacency

def has_river_edge(tile):
    x,y=tile
    flags=river_flags.get((x,y),{})
    if flags.get('NE') or flags.get('NW') or flags.get('W'):
        return True
    # check opposite edges via neighbors
    nE = neighbor(x,y,'E')
    if nE and river_flags.get(nE,{}).get('W'):
        return True
    nSE = neighbor(x,y,'SE')
    if nSE and river_flags.get(nSE,{}).get('NW'):
        return True
    nSW = neighbor(x,y,'SW')
    if nSW and river_flags.get(nSW,{}).get('NE'):
        return True
    return False

# hex distance with wrap in x

def axial_distance(a,b):
    aq,ar=offset_to_axial(*a)
    bq,br=offset_to_axial(*b)
    return (abs(aq-bq)+abs(ar-br)+abs(aq+ar-bq-br))//2


def hex_distance(a,b):
    # consider wrap in x
    if not wrap_x:
        return axial_distance(a,b)
    ax,ay=a; bx,by=b
    # try shifting b by +/- width
    best=None
    for dx in (0, width, -width):
        b2=(bx+dx, by)
        d=axial_distance(a,b2)
        if best is None or d<best:
            best=d
    return best

# tile properties

WATER_TERRAINS={'TERRAIN_COAST','TERRAIN_OCEAN'}

for t in plots.values():
    terrain=t['terrain']
    t['is_water']=terrain in WATER_TERRAINS
    t['is_mountain']=terrain.endswith('_MOUNTAIN')

# buildable land tile for standard districts

def is_buildable_land(tile):
    t=plots[tile]
    if t['is_water']:
        return False
    if t['is_mountain']:
        return False
    if t.get('impassable'):
        return False
    # disallow geothermal fissure? (feature)
    if t.get('feature') == 'FEATURE_GEOTHERMAL_FISSURE':
        return False
    return True

# base adjacency

def base_adjacency(tile, district_type):
    adj=0.0
    for n in neighbors(*tile):
        nt=plots[n]
        feat=nt.get('feature')
        terr=nt['terrain']
        if district_type=='CAMPUS':
            if terr.endswith('_MOUNTAIN'):
                adj+=1
            if feat=='FEATURE_GEOTHERMAL_FISSURE':
                adj+=1
            if feat=='FEATURE_REEF':
                adj+=1
        elif district_type=='HOLY_SITE':
            if terr.endswith('_MOUNTAIN'):
                adj+=1
        elif district_type=='COMMERCIAL_HUB':
            # river adjacency from tile itself
            pass
        elif district_type=='THEATER_SQUARE':
            pass
        elif district_type=='INDUSTRIAL_ZONE':
            pass
    if district_type=='COMMERCIAL_HUB':
        if has_river_edge(tile):
            adj+=2
    return adj

# adjacency from districts
DISTRICT_ADJ_FACTOR={'CAMPUS':0.5,'HOLY_SITE':0.5,'COMMERCIAL_HUB':1.0,'THEATER_SQUARE':1.0,'INDUSTRIAL_ZONE':0.0}

DISTRICTS=['CAMPUS','HOLY_SITE','COMMERCIAL_HUB','THEATER_SQUARE']

best=None
best_detail=None

# precompute base adjacency for each tile/district
base_adj = {d:{} for d in DISTRICTS}
for (x,y) in plots:
    if is_buildable_land((x,y)):
        for d in DISTRICTS:
            base_adj[d][(x,y)] = base_adjacency((x,y), d)

buildable_tiles=[tile for tile in plots if is_buildable_land(tile)]

# candidate city centers
city_candidates=buildable_tiles

for center in city_candidates:
    # tiles within 3
    in_range=[tile for tile in buildable_tiles if tile!=center and hex_distance(center,tile)<=3]
    if len(in_range)<3:
        continue
    # precompute adjacency to city center for each tile
    center_adj = {tile:(1 if center in neighbors(*tile) else 0) for tile in in_range}
    # reduce tiles to those with some base adjacency or near center? to speed
    # keep all for correctness
    # iterate tile combinations
    for tiles in itertools.combinations(in_range,3):
        # adjacency between tiles
        adj_pairs = {}
        for i in range(3):
            for j in range(i+1,3):
                if tiles[j] in neighbors(*tiles[i]):
                    adj_pairs[(i,j)] = True
        # assign districts types permutations
        for dists in itertools.permutations(DISTRICTS,3):
            total=0.0
            adj_detail={}
            # compute adjacency for each district
            for i,(tile,dist) in enumerate(zip(tiles,dists)):
                adj = base_adj[dist][tile]
                # district adjacency
                factor = DISTRICT_ADJ_FACTOR[dist]
                if factor:
                    # count adjacent districts among other placed + city center
                    count = center_adj[tile]
                    for j in range(3):
                        if j==i: continue
                        # adjacency check
                        if (min(i,j),max(i,j)) in adj_pairs:
                            count += 1
                    adj += factor*count
                # store
                adj_detail[dist]=adj
                total += adj
            if best is None or total>best:
                best=total
                best_detail=(center, tiles, dists, adj_detail, total)

print('best', best_detail)
